```sql
SELECT
    COALESCE(
        (SELECT SUM(total_amount)
         FROM orders
         WHERE status = 'PAID'
           AND paid_at BETWEEN '2026-02-01' AND '2026-02-28'
        ), 0
    ) -
    COALESCE(
        (SELECT SUM(refund_amount)
         FROM refunds
         WHERE refunded_at BETWEEN '2026-02-01' AND '2026-02-28'
        ), 0
    ) AS earnings;
```

